begin;
set local search_path=extensions,public,private;
select no_plan();
update private.private_locations set verified_at=now();
insert into auth.sessions(id,user_id) values
 ('97000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001'),
 ('97000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000002'),
 ('97000000-0000-4000-8000-000000000003','10000000-0000-0000-0000-000000000003');
insert into storage.objects(bucket_id,name,owner_id) values('profile-photos','10000000-0000-0000-0000-000000000002/profile.jpg','10000000-0000-0000-0000-000000000002');
insert into public.conversations(id,participant_low,participant_high,created_by) values('97100000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001');
insert into public.conversation_members(conversation_id,user_id) values('97100000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001'),('97100000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000002');
insert into public.messages(id,conversation_id,sender_id,body) values('97100000-0000-4000-8000-000000000002','97100000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Synthetic private message');
select set_config('test.notification',(select id::text from public.notifications where direct_message_id='97100000-0000-4000-8000-000000000002'),true);
insert into public.albums(id,owner_id,name) values('97200000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Session guard');
insert into public.album_shares(id,album_id,owner_id,recipient_id,conversation_id,access_mode,status,shared_version,accepted_at)
 values('97200000-0000-4000-8000-000000000002','97200000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','97100000-0000-4000-8000-000000000001','view_once','accepted',1,now());
insert into public.groups(id,owner_id,name) values('97300000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Session group');
insert into public.group_members(group_id,profile_id,role,status) values
 ('97300000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','owner','active'),
 ('97300000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000002','member','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims','{"session_id":"97000000-0000-4000-8000-000000000002"}',true);
select ok(private.account_is_active(),'live Auth session is active');
select ok(private.current_user_is_ready(true),'ready member with live session passes location check');
select lives_ok($$select public.check_account_access()$$,'Data API accepts current session');
select is((select count(*) from public.profiles),1::bigint,'current session can read own profile');
select is((select count(*) from storage.objects where name='10000000-0000-0000-0000-000000000002/profile.jpg'),1::bigint,'current session can read owned approved Storage object');
select lives_ok($$select public.export_my_account()$$,'current session can export own data');
select lives_ok($$select public.list_messages_page('97100000-0000-4000-8000-000000000001')$$,'current session reads conversation');
select lives_ok($$select public.list_group_members('97300000-0000-4000-8000-000000000001')$$,'current session reads group');
select set_config('test.viewer',public.open_album_share_once('97200000-0000-4000-8000-000000000002','97200000-0000-4000-8000-000000000003')::text,true);
select lives_ok($$select public.resolve_notification(current_setting('test.notification')::uuid)$$,'current session resolves its notification');
select public.register_push_token('ExpoPushToken[synthetic_expiry]','ios','en');

select set_config('request.jwt.claims','{}',true);
select ok(not private.account_is_active(),'missing session claim is denied');
select is((select count(*) from public.profiles),0::bigint,'missing session cannot read raw profile');
select throws_ok($$select public.check_account_access()$$,'42501','account_unavailable','missing session fails API pre-request');
select set_config('request.path','/rpc/delete_my_account',true);
select throws_ok($$select public.check_account_access()$$,'42501','account_unavailable','deletion path cannot bypass a missing session');
select throws_ok($$select public.delete_my_account()$$,'42501','active_session_required','deletion itself rejects missing session');
select set_config('request.jwt.claims','{"session_id":"97000000-0000-4000-8000-000000000001"}',true);
select ok(not private.account_is_active(),'another account session cannot authorize this JWT subject');
select set_config('request.jwt.claims','{"session_id":"97000000-0000-4000-8000-000000000002"}',true);
reset role;
update auth.sessions set not_after=now()-interval '1 second' where id='97000000-0000-4000-8000-000000000002';
set local role authenticated;
select ok(not private.account_is_active(),'explicitly expired Auth session is denied before JWT expiry');
select throws_ok($$select public.register_push_token('ExpoPushToken[expired_new]','ios','en')$$,'42501','active_session_required','expired session cannot register another push token');
reset role;
set local role service_role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{}',true);
select set_config('request.jwt.claim.role','service_role',true);
select is((select sum(jsonb_array_length(value->'tokens'))::bigint from jsonb_array_elements(public.claim_notification_outbox(100,'97400000-0000-4000-8000-000000000001'))),0::bigint,'expired Auth session does not receive an already queued push');
reset role;
update auth.sessions set not_after=null where id='97000000-0000-4000-8000-000000000002';
delete from auth.sessions where id='97000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claims','{"session_id":"97000000-0000-4000-8000-000000000002"}',true);
select ok(not private.account_is_active(),'deleted session cannot use its still-valid JWT');
select ok(not private.current_user_is_ready(false),'deleted session loses group and album readiness');
select is((select count(*) from public.profiles),0::bigint,'revoked JWT cannot read raw profile');
select is((select count(*) from public.messages),0::bigint,'revoked JWT cannot read raw messages');
select is((select count(*) from storage.objects),0::bigint,'revoked JWT cannot read Storage rows');
select throws_ok($$insert into public.messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),'97100000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000002','Denied')$$,'42501',null::text,'revoked JWT cannot send message');
select throws_ok($$select public.export_my_account()$$,'42501','account_unavailable','revoked JWT cannot export data');
select throws_ok($$select public.list_messages_page('97100000-0000-4000-8000-000000000001')$$,'42501',null::text,'revoked JWT cannot call conversation definer');
select throws_ok($$select public.list_group_members('97300000-0000-4000-8000-000000000001')$$,'42501',null::text,'revoked JWT cannot call group definer');
select throws_ok($$select public.refresh_album_share('97200000-0000-4000-8000-000000000002',(current_setting('test.viewer')::jsonb->>'session_id')::uuid)$$,'42501','album_share_locked','revoked JWT cannot renew still-open album session');
select throws_ok($$select public.resolve_notification(current_setting('test.notification')::uuid)$$,'42501','notification_unavailable','revoked JWT cannot resolve a private notification');
select throws_ok($$select public.delete_my_account()$$,'42501','active_session_required','revoked JWT cannot request deletion');
reset role;
select is((select count(*) from private.push_tokens where expo_push_token='ExpoPushToken[synthetic_expiry]'),0::bigint,'session deletion removes delivery token');
select is((select count(*) from private.account_deletion_jobs where account_id='10000000-0000-0000-0000-000000000002'),0::bigint,'denied deletion did not create a job');
update public.profiles set onboarding_completed_at=null,special_category_consent_at=null where id='10000000-0000-0000-0000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claims','{"session_id":"97000000-0000-4000-8000-000000000003"}',true);
select set_config('request.path','/rpc/complete_onboarding_profile',true);
select ok(private.account_is_active(),'new member with an active session does not need completed onboarding');
select ok(not private.current_user_is_ready(false),'new member still needs consent before social features');
select lives_ok($$select public.check_account_access()$$,'new-member API admission remains available');
select lives_ok($$select public.complete_onboarding_profile('{"dateOfBirth":"1990-01-01","displayName":"Fresh member","identity":["queer"],"lookingFor":["friends"],"bio":"Hello","region":"hofudborgarsvaedid","locale":"en","sensitiveDataConsent":true,"privacyAccepted":true,"termsAccepted":true,"guidelinesAccepted":true}')$$,'active new member can complete atomic onboarding');
select * from finish();
rollback;
